package com.example.expenses

import androidx.room.Entity
import androidx.room.PrimaryKey

// Money is stored as whole cents (a Long), never as Double, so 0.1 + 0.2 never goes wrong.
@Entity(tableName = "expenses")
data class Expense(
    @PrimaryKey(autoGenerate = true) val id: Long = 0,
    val title: String,
    val amountCents: Long,
    val category: String,
    val dateMillis: Long = System.currentTimeMillis()
)

data class CategoryTotal(val category: String, val total: Long)

val categoryNames = listOf("Food", "Transport", "Bills", "Shopping", "Fun", "Other")

fun Long.asMoney(): String = "%d.%02d".format(this / 100, this % 100)

/** Turns text such as "12.5" into 1250 cents. Returns null when the text is not a positive amount. */
fun parseCents(text: String): Long? {
    val value = text.trim().toBigDecimalOrNull() ?: return null
    if (value.signum() <= 0) return null
    return value.movePointRight(2).setScale(0, java.math.RoundingMode.HALF_UP).toLong()
}

package com.example.expenses

import androidx.room.Dao
import androidx.room.Delete
import androidx.room.Insert
import androidx.room.Query
import kotlinx.coroutines.flow.Flow

@Dao
interface ExpenseDao {
    @Query("SELECT * FROM expenses ORDER BY dateMillis DESC")
    fun observeAll(): Flow<List<Expense>>

    // The database does the adding up. The result maps straight onto CategoryTotal.
    @Query("SELECT category, SUM(amountCents) AS total FROM expenses GROUP BY category ORDER BY total DESC")
    fun observeTotals(): Flow<List<CategoryTotal>>

    @Query("SELECT COALESCE(SUM(amountCents), 0) FROM expenses")
    fun observeGrandTotal(): Flow<Long>

    @Insert
    suspend fun insert(expense: Expense)

    @Delete
    suspend fun delete(expense: Expense)
}

package com.example.expenses

import android.content.Context
import androidx.room.Database
import androidx.room.Room
import androidx.room.RoomDatabase

@Database(entities = [Expense::class], version = 1, exportSchema = false)
abstract class ExpenseDatabase : RoomDatabase() {
    abstract fun dao(): ExpenseDao

    companion object {
        @Volatile private var instance: ExpenseDatabase? = null
        fun get(context: Context): ExpenseDatabase = instance ?: synchronized(this) {
            instance ?: Room.databaseBuilder(context.applicationContext, ExpenseDatabase::class.java, "expenses.db")
                .build().also { instance = it }
        }
    }
}

