package com.example.fitness

import android.content.Context
import android.hardware.Sensor
import android.hardware.SensorEvent
import android.hardware.SensorEventListener
import android.hardware.SensorManager
import kotlinx.coroutines.channels.awaitClose
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.callbackFlow

// The step counter sensor reports total steps since the phone started.
// This Flow emits that total while someone collects it, and unregisters when they stop.
class StepSensor(context: Context) {
    private val manager = context.getSystemService(Context.SENSOR_SERVICE) as SensorManager
    private val sensor: Sensor? = manager.getDefaultSensor(Sensor.TYPE_STEP_COUNTER)

    val available: Boolean get() = sensor != null

    fun totals(): Flow<Float> = callbackFlow {
        val listener = object : SensorEventListener {
            override fun onSensorChanged(event: SensorEvent) {
                trySend(event.values[0])
            }

            override fun onAccuracyChanged(sensor: Sensor?, accuracy: Int) {
            }
        }
        if (sensor != null) {
            manager.registerListener(listener, sensor, SensorManager.SENSOR_DELAY_UI)
        }
        awaitClose { manager.unregisterListener(listener) }
    }
}

package com.example.fitness

import androidx.room.Dao
import androidx.room.Database
import androidx.room.Entity
import androidx.room.PrimaryKey
import androidx.room.Query
import androidx.room.RoomDatabase
import androidx.room.Upsert
import kotlinx.coroutines.flow.Flow

// one row for each day: date key like 2026-11-04
@Entity(tableName = "day_steps")
data class DaySteps(
    @PrimaryKey val day: String,
    val steps: Int,
    val baseline: Float,
)

@Dao
interface StepsDao {
    @Query("SELECT * FROM day_steps ORDER BY day DESC LIMIT 7")
    fun lastWeek(): Flow<List<DaySteps>>

    @Query("SELECT * FROM day_steps WHERE day = :day")
    suspend fun forDay(day: String): DaySteps?

    @Upsert
    suspend fun save(row: DaySteps)
}

@Database(entities = [DaySteps::class], version = 1, exportSchema = false)
abstract class FitnessDatabase : RoomDatabase() {
    abstract fun steps(): StepsDao
}

package com.example.fitness

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import java.time.LocalDate
import kotlinx.coroutines.Job
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch

class FitnessViewModel(
    private val sensor: StepSensor,
    private val dao: StepsDao,
) : ViewModel() {

    val sensorAvailable: Boolean get() = sensor.available
    val goal = 8000

    val week: StateFlow<List<DaySteps>> = dao.lastWeek()
        .stateIn(viewModelScope, SharingStarted.WhileSubscribed(5000), emptyList())

    private var tracking: Job? = null

    // Call after the user allowed activity recognition (Android 10 and newer).
    fun startTracking() {
        if (tracking != null || !sensor.available) return
        tracking = viewModelScope.launch {
            sensor.totals().collect { total ->
                val today = LocalDate.now().toString()
                val row = dao.forDay(today) ?: DaySteps(today, 0, total)
                // if the phone restarted, the total is lower than the saved baseline
                val baseline = if (total < row.baseline) 0f else row.baseline
                dao.save(row.copy(steps = (total - baseline).toInt(), baseline = baseline))
            }
        }
    }

    override fun onCleared() {
        tracking?.cancel()
    }
}

fun progress(steps: Int, goal: Int): Float {
    if (goal <= 0) return 0f
    return (steps.toFloat() / goal).coerceIn(0f, 1f)
}

