package com.example.bank

import android.content.Context
import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import android.util.Base64
import java.security.KeyStore
import javax.crypto.Cipher
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey
import javax.crypto.spec.GCMParameterSpec

// Keeps the login token encrypted. The AES key lives in the Android Keystore and cannot be read out.
class TokenVault(context: Context) {
    private val prefs = context.getSharedPreferences("vault", Context.MODE_PRIVATE)
    private val alias = "bank_token_key"

    private fun key(): SecretKey {
        val store = KeyStore.getInstance("AndroidKeyStore").apply { load(null) }
        (store.getKey(alias, null) as? SecretKey)?.let { return it }
        val generator = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, "AndroidKeyStore")
        generator.init(
            KeyGenParameterSpec.Builder(alias, KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT)
                .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
                .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
                .build(),
        )
        return generator.generateKey()
    }

    fun save(token: String) {
        val cipher = Cipher.getInstance("AES/GCM/NoPadding")
        cipher.init(Cipher.ENCRYPT_MODE, key())
        val encrypted = cipher.doFinal(token.toByteArray(Charsets.UTF_8))
        prefs.edit()
            .putString("iv", Base64.encodeToString(cipher.iv, Base64.NO_WRAP))
            .putString("data", Base64.encodeToString(encrypted, Base64.NO_WRAP))
            .apply()
    }

    fun read(): String? {
        val iv = prefs.getString("iv", null) ?: return null
        val data = prefs.getString("data", null) ?: return null
        return try {
            val cipher = Cipher.getInstance("AES/GCM/NoPadding")
            cipher.init(Cipher.DECRYPT_MODE, key(), GCMParameterSpec(128, Base64.decode(iv, Base64.NO_WRAP)))
            String(cipher.doFinal(Base64.decode(data, Base64.NO_WRAP)), Charsets.UTF_8)
        } catch (e: Exception) {
            null
        }
    }

    fun clear() {
        prefs.edit().clear().apply()
    }
}

package com.example.bank

import kotlinx.serialization.Serializable

@Serializable
data class LoginBody(val username: String, val password: String)

@Serializable
data class LoginReply(val token: String)

@Serializable
data class Transaction(
    val id: String,
    val title: String,
    val amountCents: Long,      // negative = money out
    val date: String,
)

// Pure rules, easy to test.
object BankRules {
    fun balance(list: List<Transaction>): Long = list.sumOf { it.amountCents }

    fun canTransfer(balanceCents: Long, amountCents: Long): Boolean {
        return amountCents > 0 && amountCents <= balanceCents
    }

    fun mask(account: String): String {
        if (account.length <= 4) return account
        return "•".repeat(account.length - 4) + account.takeLast(4)
    }
}

fun Long.asMoney(): String {
    val sign = if (this < 0) "-" else ""
    val abs = kotlin.math.abs(this)
    return sign + (abs / 100) + "." + (abs % 100).toString().padStart(2, '0')
}

package com.example.bank

import okhttp3.Interceptor
import okhttp3.Response
import retrofit2.http.Body
import retrofit2.http.GET
import retrofit2.http.POST

// This is the contract your own bank-style backend must provide.
// Never ship real banking features without a server that enforces every rule.
interface BankApi {
    @POST("login")
    suspend fun login(@Body body: LoginBody): LoginReply

    @GET("transactions")
    suspend fun transactions(): List<Transaction>

    @POST("transfer")
    suspend fun transfer(@Body body: TransferBody)
}

@kotlinx.serialization.Serializable
data class TransferBody(val toAccount: String, val amountCents: Long)

class BearerInterceptor(private val vault: TokenVault) : Interceptor {
    override fun intercept(chain: Interceptor.Chain): Response {
        val token = vault.read()
        val builder = chain.request().newBuilder()
        if (token != null) builder.header("Authorization", "Bearer " + token)
        return chain.proceed(builder.build())
    }
}

package com.example.bank

import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch

data class BankState(
    val loggedIn: Boolean = false,
    val unlocked: Boolean = false,     // passed the biometric check this session
    val loading: Boolean = false,
    val error: String? = null,
    val transactions: List<Transaction> = emptyList(),
    val message: String? = null,
)

class BankViewModel(
    private val api: BankApi,
    private val vault: TokenVault,
) : ViewModel() {

    private val _state = MutableStateFlow(BankState(loggedIn = vault.read() != null))
    val state: StateFlow<BankState> = _state.asStateFlow()

    fun login(user: String, password: String) {
        if (user.isBlank() || password.length < 8) {
            _state.update { it.copy(error = "Enter your user name and a password of 8 or more characters") }
            return
        }
        _state.update { it.copy(loading = true, error = null) }
        viewModelScope.launch {
            try {
                val reply = api.login(LoginBody(user.trim(), password))
                vault.save(reply.token)
                _state.update { it.copy(loggedIn = true, unlocked = true, loading = false) }
                refresh()
            } catch (e: Exception) {
                _state.update { it.copy(loading = false, error = "Sign in failed. Check your details and connection.") }
            }
        }
    }

    fun unlocked() {
        _state.update { it.copy(unlocked = true) }
        refresh()
    }

    fun refresh() {
        viewModelScope.launch {
            try {
                val list = api.transactions()
                _state.update { it.copy(transactions = list, error = null) }
            } catch (e: Exception) {
                _state.update { it.copy(error = "Could not load transactions") }
            }
        }
    }

    fun transfer(to: String, amountText: String) {
        val cents = parse(amountText)
        val balance = BankRules.balance(_state.value.transactions)
        if (cents == null || !BankRules.canTransfer(balance, cents)) {
            _state.update { it.copy(message = "Enter an amount up to your balance") }
            return
        }
        viewModelScope.launch {
            try {
                api.transfer(TransferBody(to, cents))   // the server checks everything again
                _state.update { it.copy(message = "Transfer sent") }
                refresh()
            } catch (e: Exception) {
                _state.update { it.copy(message = "Transfer failed") }
            }
        }
    }

    fun logout() {
        vault.clear()
        _state.value = BankState()
    }

    private fun parse(text: String): Long? {
        val m = Regex("^(\\d+)(\\.(\\d{1,2}))?$").matchEntire(text.trim()) ?: return null
        val whole = m.groupValues[1].toLong()
        val frac = m.groupValues[3].padEnd(2, '0').ifEmpty { "0" }.toLong()
        return whole * 100 + frac
    }
}

