package com.example.jobs

import kotlinx.serialization.Serializable

@Serializable
data class Job(
    val id: String,
    val title: String,
    val company: String,
    val location: String,
    val type: String = "Full-time",       // Full-time, Part-time, Internship, Contract
    val remote: Boolean = false,
    val description: String = "",
)

@Serializable
data class ApplyResult(val ok: Boolean, val message: String = "")

data class JobFilter(
    val query: String = "",
    val remoteOnly: Boolean = false,
    val type: String? = null,
)

// Filtering is done in plain Kotlin, so it is easy to test. A real backend would also filter on the server.
fun List<Job>.filtered(f: JobFilter): List<Job> {
    val q = f.query.trim().lowercase()
    return filter { job ->
        (q.isEmpty() || job.title.lowercase().contains(q) || job.company.lowercase().contains(q) || job.location.lowercase().contains(q)) &&
            (!f.remoteOnly || job.remote) &&
            (f.type == null || job.type == f.type)
    }
}

// Accept only resume files of reasonable size and type before uploading.
fun resumeProblem(mime: String?, sizeBytes: Long): String? {
    val allowed = setOf(
        "application/pdf",
        "application/msword",
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    )
    return when {
        mime == null || mime !in allowed -> "Choose a PDF or Word file."
        sizeBytes <= 0 -> "The file is empty."
        sizeBytes > 5L * 1024 * 1024 -> "The file must be 5 MB or smaller."
        else -> null
    }
}

package com.example.jobs

import okhttp3.MultipartBody
import okhttp3.RequestBody
import retrofit2.http.GET
import retrofit2.http.Multipart
import retrofit2.http.POST
import retrofit2.http.Part
import retrofit2.http.Path
import retrofit2.http.Query

// The contract your own backend provides. The job list and applications are stored on the server.
interface JobApi {
    @GET("jobs")
    suspend fun jobs(@Query("page") page: Int): List<Job>

    @Multipart
    @POST("jobs/{id}/apply")
    suspend fun apply(
        @Path("id") id: String,
        @Part("cover") cover: RequestBody,
        @Part resume: MultipartBody.Part,
    ): ApplyResult
}

package com.example.jobs

import android.content.ContentResolver
import android.net.Uri
import android.provider.OpenableColumns
import androidx.lifecycle.ViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.flow.update
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.MultipartBody
import okhttp3.RequestBody.Companion.toRequestBody

data class JobsState(
    val all: List<Job> = emptyList(),
    val loading: Boolean = true,
    val error: String? = null,
    val filter: JobFilter = JobFilter(),
    val applyMessage: String? = null,
    val applying: Boolean = false,
) {
    val shown: List<Job> get() = all.filtered(filter)
}

class JobViewModel(private val api: JobApi) : ViewModel() {
    private val _state = MutableStateFlow(JobsState())
    val state: StateFlow<JobsState> = _state.asStateFlow()

    init {
        load()
    }

    fun load() {
        _state.update { it.copy(loading = true, error = null) }
        viewModelScope.launch {
            try {
                val jobs = api.jobs(page = 1)
                _state.update { it.copy(all = jobs, loading = false) }
            } catch (e: Exception) {
                _state.update { it.copy(loading = false, error = "Could not load jobs. Pull to try again.") }
            }
        }
    }

    fun setFilter(f: JobFilter) {
        _state.update { it.copy(filter = f) }
    }

    fun apply(resolver: ContentResolver, jobId: String, cover: String, resume: Uri) {
        viewModelScope.launch {
            val mime = resolver.getType(resume)
            val size = withContext(Dispatchers.IO) {
                resolver.query(resume, null, null, null, null)?.use { c ->
                    val col = c.getColumnIndex(OpenableColumns.SIZE)
                    if (c.moveToFirst() && col >= 0) c.getLong(col) else 0L
                } ?: 0L
            }
            val problem = resumeProblem(mime, size)
            if (problem != null) {
                _state.update { it.copy(applyMessage = problem) }
                return@launch
            }
            _state.update { it.copy(applying = true, applyMessage = null) }
            try {
                val bytes = withContext(Dispatchers.IO) { resolver.openInputStream(resume)!!.use { it.readBytes() } }
                val part = MultipartBody.Part.createFormData(
                    "resume",
                    "resume",
                    bytes.toRequestBody(mime!!.toMediaType()),
                )
                val result = api.apply(jobId, cover.take(2000).toRequestBody("text/plain".toMediaType()), part)
                _state.update { it.copy(applying = false, applyMessage = if (result.ok) "Application sent" else result.message) }
            } catch (e: Exception) {
                _state.update { it.copy(applying = false, applyMessage = "Could not send the application. Try again.") }
            }
        }
    }

    fun messageShown() {
        _state.update { it.copy(applyMessage = null) }
    }
}

